*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS30700.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
    var array_grid = [grd_List];
    setResizeGrid(array_grid);
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        txb_STD_CD.setValue(((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : ""));
        txb_ISU_NM.setValue(((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : ""));
        edt_FROM_TRNSM_DD.setValue(((arrPar.length >= 1) && (arrPar[2] != undefined) ? arrPar[2] : ""));
        scwin.ins_search();
    }
};



/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    //ins_combo_set(dts_STD_CD_APPL_CONTN_TP_CD, vScrenID, SCREN_PROCS_TP_CD_01 ,"03425","ALL"); //상품구분 		

};

/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_FROM_TRNSM_DD.setValue(sToday);
    edt_TO_TRNSM_DD.setValue(sToday);
    $c.stf.showObj(panel_5, false);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_List.removeAll();
    txb_TotalCnt.setValue("총 0건");
};


/**
 * 조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_search")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listbndCdTrsHistListInquiry" + "&outputMessageId=INS_LIST_BND_CD_TRS_HIST_LIST_INQUIRY" + "&param01=" + $c.stf.getObjectValue(edt_FROM_TRNSM_DD) + "&param02=" + $c.stf.getObjectValue(edt_TO_TRNSM_DD) + "&param03=" + $c.stf.getObjectValue(txb_STD_CD) + "&param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&param05=" + $c.stf.getObjectValue(cmb_TRNSM_YN) + "&param06=" + $c.stf.getObjectValue(txb_ISU_NM) + "&param07=" + $c.stf.getObjectValue(chb_REC_PROCS_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == "ins_search") {
        if ($c.stf.getObjectValue(edt_FROM_TRNSM_DD) == "") {
            $c.win.alert("검색 시작일을 입력하세요.");
            edt_FROM_TRNSM_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_TRNSM_DD) == "") {
            $c.win.alert("검색 종료일을 입력하세요.");
            edt_TO_TRNSM_DD.focus();
            return false;
        }

        // 일자 체크
        if ($c.stf.compareFromToDate2(edt_FROM_TRNSM_DD, edt_TO_TRNSM_DD) == false) {
            return false;
        }

        // 검색기간 일주일 단위 체크.
        if ($c.ut.cGetDifTodayInputday(edt_FROM_TRNSM_DD.getValue(), edt_TO_TRNSM_DD.getValue()) > 6) {
            $c.win.alert("검색 기간은 일주일 단위로만 가능합니다.");
            return false;
        }
    } else if (pGubun == "ins_Trans") {
        // 조회된 fax가 있는가?
        if (dts_List.getTotalRow() == 0) {
            $c.win.alert("조회된 정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        var nTrueCnt = 0;
        for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") == "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt == 0) {
            $c.win.alert("선택된 정보가 없습니다.");
            return false;
        }
    }
    return true;
};


/**
 * 전송
 */
scwin.ins_Trans = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("ins_Trans")) {
        return;
    }
    if (!confirm("전송하시겠습니까?")) {
        return;
    }
    trs_Save.Action = "/StdCdListAction.do?method=transBndCdTrsHist" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Save.Post();
};


/**
 * 전송여부가 N인 경우 체크박스 체크
 */
scwin.fn_Check = function(nRow, bCheck, bMsgShow) {
    if (dts_List.getCellData(nRow, "TRNSM_YN") == "N") {
        dts_List.setCellData(nRow, "CHK", bCheck ? "T" : "F");
    } else {
        if (bMsgShow) {
            $c.win.alert("이미 전송된 건입니다.");
        }
        dts_List.setCellData(nRow, "CHK", "F");
    }
};



/**
 * 전체 체크
 */
scwin.fn_CheckAll = function(bCheck) {
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        scwin.fn_Check(nRow, bCheck, false);
    }
};



/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.fn_GetParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue();
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    scwin.fn_Init();
    txb_STD_CD.focus();
};
scwin.txb_ISUR_CD_onchange = function() {
    //	txb_ISUR_NM.value = "";

};
scwin.img_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_FROM_TRNSM_DD_onclick = function() {
    popUpCalendar2(edt_FROM_TRNSM_DD);
};
scwin.img_TO_TRNSM_DD_onclick = function() {
    popUpCalendar2(edt_TO_TRNSM_DD);
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_List);
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_List);
    txb_TotalCnt.setValue("총 " + rowcount + "건");
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_search();
};
scwin.btn_send_onclick = function() {
    scwin.ins_Trans();
};
scwin.grd_List_OnHeadCheckClick = function(col, colid, bCheck) {
    scwin.fn_CheckAll(bCheck);
};
scwin.grd_List_OnCheckClick = function(col, colid, bCheck) {
    scwin.fn_Check(col, bCheck, true);
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (row == 0) return;
    if (colid == "STD_CD") {
        var sStdCd = dts_List.getCellData(row, "STD_CD");
        var sContnTpCd = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_CD"); // 상품구분
        var sKnd = "";
        if (sContnTpCd == "02") {
            sKnd = "주권";
        } else if (sContnTpCd == "10") {
            sKnd = "주식워런트";
        } else if (sContnTpCd == "11") {
            sKnd = "ELS_DLS";
        } else if (sContnTpCd == "12") {
            sKnd = "전자단기사채";
        }
        if (sContnTpCd == "08") {
            txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
        } else {
            txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
        }
        fn_GetPar = fn_GetParam;
        ins_ViewIsuMaster(sKnd, sStdCd);
    }
};
scwin.txb_STD_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_STD_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_ISU_NM_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_ISU_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_ISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.cmb_TRNSM_YN_OnSelChange = function() {
    scwin.ins_search();
};
scwin.img_BND_CLSS_CD_ERASER_onclick = function() {
    txb_ISUR_CD.setValue("");
    txb_ISUR_NM.setValue("");
};
